insert into public.horoscope_texts (kind, key, lang, title, body) values
  ('gochar', 1, 'en', 'Moon in your own sign', 'Feelings run strong today and you notice your own needs more than usual. Look after your health, eat on time and give yourself some quiet. A good day to start something personal, not to argue.'),
  ('gochar', 2, 'en', 'Focus on money and family', 'Attention turns to savings, food and family matters. Think before spending and choose your words carefully, since speech is sensitive today. A family meal or call brings warmth.'),
  ('gochar', 3, 'en', 'Courage and communication', 'Energy and confidence are high. Make the call, send the message or take the short trip you have been putting off. Brothers, sisters and neighbours can be helpful.'),
  ('gochar', 4, 'en', 'Home and peace of mind', 'You may feel restless or low on comfort. Stay close to home, avoid arguments with family and postpone property or vehicle decisions. Time with your mother or in a calm place helps.'),
  ('gochar', 5, 'en', 'Studies, children and creativity', 'The mind is active but can wander. Good for study, creative work and time with children, but avoid speculation and quick decisions about money. Keep promises small and realistic.'),
  ('gochar', 6, 'en', 'Victory over obstacles', 'A strong day for clearing pending work, tackling problems and handling competition. Health routines and service to others bring good results. Pending dues or loans can move forward.'),
  ('gochar', 7, 'en', 'Partnerships and people', 'Relationships, meetings and deals are favoured. Your spouse or business partner is supportive. Good for social plans, travel with others and agreements made in good faith.'),
  ('gochar', 8, 'en', 'Chandrashtama: go slowly', 'The Moon is 8th from your sign, a traditional day for caution. Avoid major decisions, risky travel and new commitments. Rest, drive carefully and keep your temper. This passes in about two days.'),
  ('gochar', 9, 'en', 'Elders, faith and fortune', 'Blessings come through teachers, elders and acts of faith. Good for prayer, learning and planning long journeys. Results are mixed for material matters, so be patient with outcomes.'),
  ('gochar', 10, 'en', 'Work and recognition', 'Your efforts at work get noticed. Good for meetings with seniors, important tasks and taking responsibility. Act with confidence and finish what you begin.'),
  ('gochar', 11, 'en', 'Gains and good news', 'One of the best days of the cycle. Income, help from friends and fulfilment of wishes are likely. Ask for what you need and enjoy time with your circle.'),
  ('gochar', 12, 'en', 'Rest and letting go', 'Expenses and tiredness may increase. Keep spending in check, sleep well and avoid starting important work. A good day for meditation, charity and finishing old tasks quietly.'),
  ('tara', 1, 'en', 'Janma Tara', 'Today''s star is your birth star. Keep things simple and look after your body and mind.'),
  ('tara', 2, 'en', 'Sampat Tara', 'A star of wealth. Favourable for money matters, purchases and new efforts.'),
  ('tara', 3, 'en', 'Vipat Tara', 'A star of obstacles. Expect small delays; double-check plans and avoid starting new ventures.'),
  ('tara', 4, 'en', 'Kshema Tara', 'A star of well-being. Good for health, comfort and steady progress.'),
  ('tara', 5, 'en', 'Pratyak Tara', 'A star of resistance. People may oppose you; stay patient and avoid confrontations.'),
  ('tara', 6, 'en', 'Sadhana Tara', 'A star of achievement. Efforts succeed; a good day to complete goals.'),
  ('tara', 7, 'en', 'Naidhana Tara', 'A difficult star. Avoid risks, travel carefully and postpone important decisions.'),
  ('tara', 8, 'en', 'Mitra Tara', 'A friendly star. Help comes from friends; good for cooperation.'),
  ('tara', 9, 'en', 'Param Mitra Tara', 'A very friendly star. Support and good results come easily today.');
